import cookieApi from './utils/cookie.js';

const TELEMETRY_ENDPOINT = 'https://gate.catch.jobs/public/v1/telemetry';

const root = typeof document !== 'undefined' ? document.documentElement : null;
const doc = typeof document !== 'undefined' ? document : null;

const telemetryState = {
  endpoint: TELEMETRY_ENDPOINT,
  basePayload: null,
  enabled: false,
  postId: '',
};

function resolveEnabledFlag() {
  if (!root?.dataset) {
    return false;
  }

  const raw = root.dataset.analyticsEnabled;
  if (raw == null) {
    return true;
  }

  const normalized = String(raw).toLowerCase();
  return normalized !== 'false' && normalized !== '0' && normalized !== 'off';
}

function resolvePostId() {
  if (!doc) {
    return '';
  }

  const contentNode = doc.querySelector('[data-content-id]');
  if (contentNode?.dataset?.contentId) {
    return contentNode.dataset.contentId;
  }

  const jobNode = doc.querySelector('[data-job-id]');
  if (jobNode?.dataset?.jobId) {
    return jobNode.dataset.jobId;
  }

  return '';
}

function buildBasePayload() {
  const lang = root?.getAttribute('lang') || '';
  const theme = root?.dataset?.theme || '';
  const url = typeof window !== 'undefined' ? window.location.href : '';

  return {
    url,
    referrer: doc?.referrer || '',
    sessionId: cookieApi.getSessionId?.() || '',
    userId: cookieApi.getUserId?.() || '',
    lang,
    theme,
  };
}

function withPostId(data, postId) {
  if (!postId) {
    return data || {};
  }

  return {
    postId,
    ...(data || {}),
  };
}

function sendEvent(payload, { useBeacon = false } = {}) {
  if (!telemetryState.enabled || !telemetryState.endpoint) {
    return false;
  }

  const body = JSON.stringify(payload);
  if (useBeacon && typeof navigator !== 'undefined' && typeof navigator.sendBeacon === 'function') {
    const blob = new Blob([body], { type: 'application/json' });
    return navigator.sendBeacon(telemetryState.endpoint, blob);
  }

  if (typeof fetch !== 'function') {
    return false;
  }

  fetch(telemetryState.endpoint, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
    },
    body,
    keepalive: useBeacon,
  }).catch(() => {});

  return true;
}

function trackEvent({ type, name, value = '', data = {}, useBeacon = false }) {
  if (!telemetryState.basePayload) {
    return false;
  }

  return sendEvent(
    {
      ...telemetryState.basePayload,
      type,
      name,
      value: String(value || ''),
      data: withPostId(data, telemetryState.postId),
    },
    { useBeacon }
  );
}

function initViewTracking() {
  trackEvent({
    type: 'view',
    name: 'page_view',
    value: '',
    data: {},
  });
}

function initLeaveTracking() {
  if (!doc || typeof window === 'undefined') {
    return;
  }

  let leaveSent = false;
  const sendLeave = () => {
    if (leaveSent) {
      return;
    }
    leaveSent = true;
    trackEvent({
      type: 'leave',
      name: 'page_leave',
      value: '',
      data: {},
      useBeacon: true,
    });
  };

  doc.addEventListener('visibilitychange', () => {
    if (doc.visibilityState === 'hidden') {
      sendLeave();
    }
  });
  window.addEventListener('pagehide', sendLeave);
  window.addEventListener('beforeunload', sendLeave);
}

function initScrollTracking() {
  if (typeof window === 'undefined' || !doc) {
    return;
  }

  const thresholds = [20, 40, 60, 80, 100];
  const fired = new Set();
  let ticking = false;

  const onScroll = () => {
    if (ticking) {
      return;
    }

    ticking = true;
    window.requestAnimationFrame(() => {
      ticking = false;

      const scrollTop = window.scrollY || doc.documentElement.scrollTop || 0;
      const docHeight = Math.max(doc.documentElement.scrollHeight, doc.body?.scrollHeight || 0);
      const viewportHeight = window.innerHeight || 1;
      const total = Math.max(1, docHeight - viewportHeight);
      const percent = Math.min(100, Math.round((scrollTop / total) * 100));

      thresholds.forEach((threshold) => {
        if (percent < threshold || fired.has(threshold)) {
          return;
        }

        fired.add(threshold);
        trackEvent({
          type: 'scroll',
          name: 'scroll_depth',
          value: String(threshold),
          data: { percent: threshold },
        });
      });
    });
  };

  window.addEventListener('scroll', onScroll, { passive: true });
  onScroll();
}

function initVitalsTracking() {
  if (typeof window === 'undefined' || typeof PerformanceObserver === 'undefined') {
    return;
  }

  const reportVital = (name, value, data = {}) => {
    if (!name) {
      return;
    }

    const normalizedValue =
      typeof value === 'number'
        ? name === 'CLS'
          ? value.toFixed(3)
          : String(Math.round(value))
        : String(value || '');

    trackEvent({
      type: 'vital',
      name: String(name).toLowerCase(),
      value: normalizedValue,
      data,
    });
  };

  const paintObserver = new PerformanceObserver((list) => {
    const entry = list.getEntries().find((item) => item.name === 'first-contentful-paint');
    if (!entry) {
      return;
    }

    reportVital('fcp', entry.startTime, { entryType: entry.entryType });
    paintObserver.disconnect();
  });
  try {
    paintObserver.observe({ type: 'paint', buffered: true });
  } catch {
    return;
  }

  let lcpEntry = null;
  const lcpObserver = new PerformanceObserver((list) => {
    const entries = list.getEntries();
    if (entries.length > 0) {
      lcpEntry = entries[entries.length - 1];
    }
  });
  try {
    lcpObserver.observe({ type: 'largest-contentful-paint', buffered: true });
  } catch {
    return;
  }

  let lcpReported = false;
  const finalizeLcp = () => {
    if (lcpReported) {
      return;
    }
    lcpReported = true;

    if (lcpEntry) {
      reportVital('lcp', lcpEntry.startTime, { entryType: lcpEntry.entryType });
    }
    lcpObserver.disconnect();
  };

  window.addEventListener('pagehide', finalizeLcp, { once: true });
  doc?.addEventListener(
    'visibilitychange',
    () => {
      if (doc.visibilityState === 'hidden') {
        finalizeLcp();
      }
    },
    { once: true }
  );
}

function initContentLinkTracking() {
  if (!doc || typeof window === 'undefined') {
    return;
  }

  const linkEventState = { href: '', time: 0 };

  const shouldSendLinkEvent = (href) => {
    const now = Date.now();
    if (linkEventState.href === href && now - linkEventState.time < 500) {
      return false;
    }

    linkEventState.href = href;
    linkEventState.time = now;
    return true;
  };

  const handleLinkEvent = (event, trigger) => {
    const link = event.target?.closest?.('a[href]');
    if (!link) {
      return;
    }

    const container = link.closest('.post-body, .page, .collection-content, .external-content, article');
    if (!container) {
      return;
    }

    if (link.dataset?.metric != null || link.dataset?.metrics != null) {
      return;
    }

    const href = link.getAttribute('href') || '';
    if (!href || href.startsWith('#') || href.startsWith('mailto:') || href.startsWith('tel:')) {
      return;
    }

    let linkUrl;
    try {
      linkUrl = new URL(href, window.location.href);
    } catch {
      return;
    }

    if (linkUrl.origin === window.location.origin) {
      return;
    }

    if (!shouldSendLinkEvent(linkUrl.href)) {
      return;
    }

    trackEvent({
      type: 'custom',
      name: 'external_link_click',
      value: '',
      data: {
        source: 'content',
        href: linkUrl.href,
        host: linkUrl.host,
        path: linkUrl.pathname,
        target: link.getAttribute('target') || '',
        text: (link.textContent || '').trim().slice(0, 120),
        trigger,
      },
      useBeacon: true,
    });
  };

  doc.addEventListener('click', (event) => handleLinkEvent(event, 'click'), { capture: true });
  doc.addEventListener('auxclick', (event) => handleLinkEvent(event, 'auxclick'), { capture: true });
  doc.addEventListener(
    'keydown',
    (event) => {
      if (event.key !== 'Enter' && event.key !== ' ') {
        return;
      }
      handleLinkEvent(event, 'keydown');
    },
    { capture: true }
  );
}

function readMetricMeta(dataset) {
  const meta = {};

  Object.entries(dataset || {}).forEach(([key, value]) => {
    if (!key.startsWith('metricMeta')) {
      return;
    }

    const normalizedKey = key.slice('metricMeta'.length);
    if (!normalizedKey) {
      return;
    }

    const metaKey = normalizedKey.charAt(0).toLowerCase() + normalizedKey.slice(1);
    meta[metaKey] = value;
  });

  return meta;
}

function buildMetricPayloadFromElement(element) {
  if (!element) {
    return null;
  }

  const name = element.dataset?.metricName || element.dataset?.metrics || '';
  if (!name) {
    return null;
  }

  const type = element.dataset?.metricType || 'custom';
  const source = element.dataset?.metricSource || '';
  const meta = readMetricMeta(element.dataset);
  const value = element.dataset?.metricValue || (name === 'share_click' ? meta.channel || '' : '');
  const tag = element.tagName ? element.tagName.toLowerCase() : '';

  return {
    type,
    name,
    value,
    data: {
      source,
      meta,
      tag,
      id: element.id || '',
      text: (element.textContent || '').trim().slice(0, 120),
      href: element.tagName === 'A' ? element.getAttribute('href') || '' : '',
      target: element.tagName === 'A' ? element.getAttribute('target') || '' : '',
    },
  };
}

function trackMetricElement(element) {
  const metricPayload = buildMetricPayloadFromElement(element);
  if (!metricPayload) {
    return false;
  }

  return trackEvent(metricPayload);
}

function bindMetricTracking() {
  if (!doc) {
    return;
  }

  doc.addEventListener('click', (event) => {
    const target = event.target?.closest?.('[data-metric], [data-metrics]');
    if (!target) {
      return;
    }

    trackMetricElement(target);
  });
}

function initTelemetry() {
  if (!resolveEnabledFlag()) {
    return telemetryApi;
  }

  telemetryState.basePayload = buildBasePayload();
  telemetryState.postId = resolvePostId();
  telemetryState.enabled = true;

  initViewTracking();
  initScrollTracking();
  initVitalsTracking();
  initContentLinkTracking();
  // Intentionally not bound by default: call telemetryApi.bindMetricTracking() when needed.
  initLeaveTracking();

  return telemetryApi;
}

const telemetryApi = {
  init: initTelemetry,
  trackCustom: (name, data = {}, value = '') => {
    if (!name) {
      return false;
    }

    return trackEvent({
      type: 'custom',
      name,
      value,
      data,
    });
  },
  trackMetricElement,
  bindMetricTracking,
};

export default telemetryApi;
