import { mapLocaleToCulture, resolveLocale } from '../utils/locale.js';

const CATCHJOBS_CLIENT_ID = 'bbc12b18-9a88-457c-a2b0-554d2f113564';
const GUEST_TOKEN_STORAGE_KEY = 'catchjobs_guest_token';
const GUEST_TOKEN_EXPIRY_STORAGE_KEY = 'catchjobs_guest_token_expiry';
const TOKEN_EXPIRY_BUFFER_MS = 5 * 60 * 1000;

let guestTokenRequest = null;

const normalizeViewCount = (value) => {
  const numericValue = Number(value);
  return Number.isFinite(numericValue) ? numericValue : null;
};

const isTokenExpired = (expiry) => {
  if (!expiry) return true;
  const expiryDate = new Date(expiry);
  if (Number.isNaN(expiryDate.getTime())) return true;
  return Date.now() >= (expiryDate.getTime() - TOKEN_EXPIRY_BUFFER_MS);
};

const getStoredGuestToken = () => {
  if (typeof window === 'undefined') return null;

  try {
    const token = window.sessionStorage.getItem(GUEST_TOKEN_STORAGE_KEY);
    const expiry = window.sessionStorage.getItem(GUEST_TOKEN_EXPIRY_STORAGE_KEY);
    if (token && expiry) {
      return { token, expiry };
    }
  } catch (error) {
    console.warn('Failed to read guest token from session storage:', error);
  }

  return null;
};

const storeGuestToken = (token, expiry) => {
  if (typeof window === 'undefined') return;

  try {
    window.sessionStorage.setItem(GUEST_TOKEN_STORAGE_KEY, token);
    window.sessionStorage.setItem(GUEST_TOKEN_EXPIRY_STORAGE_KEY, expiry);
  } catch (error) {
    console.warn('Failed to store guest token in session storage:', error);
  }
};

const clearStoredGuestToken = () => {
  if (typeof window === 'undefined') return;

  try {
    window.sessionStorage.removeItem(GUEST_TOKEN_STORAGE_KEY);
    window.sessionStorage.removeItem(GUEST_TOKEN_EXPIRY_STORAGE_KEY);
  } catch (error) {
    console.warn('Failed to clear guest token from session storage:', error);
  }
};

const requestGuestToken = async (locale) => {
  const headers = {
    'Content-Type': 'application/json',
    Version: '1',
  };
  const culture = mapLocaleToCulture(locale);
  if (culture) {
    headers['X-Culture'] = culture;
  }

  const response = await fetch('https://gate.catch.jobs/auth/v1/token/guest', {
    method: 'POST',
    headers,
    body: JSON.stringify({ clientId: CATCHJOBS_CLIENT_ID }),
    cache: 'no-store',
  });

  if (!response.ok) {
    throw new Error(`Guest token failed: ${response.status} ${response.statusText}`);
  }

  const payload = await response.json();
  const token = payload?.data?.token;
  const expiry = payload?.data?.expire;

  if (!token || !expiry) {
    throw new Error('Guest token response is missing token data');
  }

  storeGuestToken(token, expiry);
  return token;
};

const getValidGuestToken = async (locale) => {
  const storedToken = getStoredGuestToken();
  if (storedToken && !isTokenExpired(storedToken.expiry)) {
    return storedToken.token;
  }

  if (!guestTokenRequest) {
    guestTokenRequest = requestGuestToken(locale)
      .catch((error) => {
        clearStoredGuestToken();
        throw error;
      })
      .finally(() => {
        guestTokenRequest = null;
      });
  }

  return guestTokenRequest;
};

const fetchJobById = async (jobId, locale) => {
  const culture = mapLocaleToCulture(locale);
  const makeHeaders = (token) => {
    const headers = {
      Authorization: `Bearer ${token}`,
      Version: '1',
    };

    if (culture) {
      headers['X-Culture'] = culture;
    }
    return headers;
  };

  let token = await getValidGuestToken(locale);
  let response = await fetch(`https://gate.catch.jobs/job/v1/${jobId}/info`, {
    method: 'GET',
    headers: makeHeaders(token),
    cache: 'no-store',
  });

  if (response.status === 401) {
    clearStoredGuestToken();
    token = await requestGuestToken(locale);
    response = await fetch(`https://gate.catch.jobs/job/v1/${jobId}/info`, {
      method: 'GET',
      headers: makeHeaders(token),
      cache: 'no-store',
    });
  }

  if (!response.ok) {
    throw new Error(`Job fetch failed: ${response.status} ${response.statusText}`);
  }

  return response.json();
};

const updateViewCountNodes = (container, viewCount) => {
  if (!container || viewCount === null) return;
  const targets = container.querySelectorAll('[data-view-count]');
  targets.forEach((target) => {
    target.textContent = String(viewCount);
  });
};

export const refreshJobViewCount = async ({ jobId, detailElement, cardElement }) => {
  if (!jobId) return null;

  try {
    const locale = resolveLocale();
    const payload = await fetchJobById(jobId, locale);
    const viewCount = normalizeViewCount(payload?.data?.job?.viewCount);
    if (viewCount === null) return null;

    updateViewCountNodes(detailElement, viewCount);
    updateViewCountNodes(cardElement, viewCount);
    return viewCount;
  } catch (error) {
    console.warn(`Failed to refresh view count for job ${jobId}:`, error);
    return null;
  }
};

export const initStandaloneJobDetailViewCount = () => {
  const detailPage = document.querySelector('div.job-detail-page[data-job-id]');
  if (!detailPage) return;
  if (detailPage.closest('section.job-detail-section')) return;

  const jobId = detailPage.getAttribute('data-job-id');
  if (!jobId) return;

  refreshJobViewCount({
    jobId,
    detailElement: detailPage,
  });
};
